Model::~Model(){ destroy(); }
bool Model::validateAsset(const std::string& path,unsigned minMeshes,unsigned minAnimations,unsigned minBones){Assimp::Importer importer;const aiScene* scene=importer.ReadFile(path,aiProcess_Triangulate);if(!scene){std::cerr<<"Asset validation failed: "<<path<<" : "<<importer.GetErrorString()<<'\n';return false;}unsigned bones=0;for(unsigned i=0;i<scene->mNumMeshes;++i)bones=std::max(bones,scene->mMeshes[i]->mNumBones);bool ok=scene->mNumMeshes>=minMeshes&&scene->mNumAnimations>=minAnimations&&bones>=minBones;if(!ok)std::cerr<<"Asset validation mismatch: "<<path<<" meshes="<<scene->mNumMeshes<<" animations="<<scene->mNumAnimations<<" bones="<<bones<<'\n';return ok;}
bool Model::hasAnimationClip(const std::string& path,const std::string& clip){Assimp::Importer importer;const aiScene* scene=importer.ReadFile(path,aiProcess_Triangulate);if(!scene)return false;for(unsigned i=0;i<scene->mNumAnimations;++i)if(std::string(scene->mAnimations[i]->mName.C_Str()).find(clip)!=std::string::npos)return true;return false;}
bool Model::validateImage(const std::string& path){int w=0,h=0,n=0;bool ok=stbi_info(path.c_str(),&w,&h,&n)!=0&&w>0&&h>0;if(!ok)std::cerr<<"Image validation failed: "<<path<<'\n';return ok;}
void Model::releaseGpu(){
    for(auto& m:meshes_){if(m.ebo)glDeleteBuffers(1,&m.ebo);if(m.vbo)glDeleteBuffers(1,&m.vbo);if(m.vao)glDeleteVertexArrays(1,&m.vao);if(m.texture)glDeleteTextures(1,&m.texture);}
    meshes_.clear(); if(fallbackTexture_)glDeleteTextures(1,&fallbackTexture_);fallbackTexture_=0;
}
void Model::destroy(){releaseGpu();scene_=nullptr;boneIds_.clear();offsets_.clear();}
GLuint Model::loadTexture(const std::string& path){
    if(path.empty())return 0;
    int w=0,h=0,n=0;stbi_set_flip_vertically_on_load(1);unsigned char* pixels=stbi_load(path.c_str(),&w,&h,&n,4);
    if(!pixels){std::cerr<<"Texture load failed: "<<path<<" ("<<stbi_failure_reason()<<")\n";return 0;}
    GLuint tex=0;glGenTextures(1,&tex);glBindTexture(GL_TEXTURE_2D,tex);glTexImage2D(GL_TEXTURE_2D,0,GL_SRGB8_ALPHA8,w,h,0,GL_RGBA,GL_UNSIGNED_BYTE,pixels);glGenerateMipmap(GL_TEXTURE_2D);
    glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_MIN_FILTER,GL_LINEAR_MIPMAP_LINEAR);glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_MAG_FILTER,GL_LINEAR);glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_WRAP_S,GL_REPEAT);glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_WRAP_T,GL_REPEAT);stbi_image_free(pixels);return tex;
}
glm::mat4 Model::toGlm(const aiMatrix4x4& a)const{return glm::mat4(a.a1,a.b1,a.c1,a.d1,a.a2,a.b2,a.c2,a.d2,a.a3,a.b3,a.c3,a.d3,a.a4,a.b4,a.c4,a.d4);}
bool Model::load(const std::string& path,const std::string& fallbackTexture){
    destroy();directory_=std::filesystem::path(path).parent_path().string();
    scene_=importer_.ReadFile(path,aiProcess_Triangulate|aiProcess_GenSmoothNormals|aiProcess_JoinIdenticalVertices|aiProcess_LimitBoneWeights|aiProcess_ImproveCacheLocality|aiProcess_FlipUVs);
    if(!scene_||!scene_->mRootNode){std::cerr<<"Model load failed: "<<path<<" : "<<importer_.GetErrorString()<<'\n';return false;}
    aiMatrix4x4 root=scene_->mRootNode->mTransformation;root.Inverse();globalInverse_=toGlm(root);
    for(unsigned mi=0;mi<scene_->mNumMeshes;++mi)for(unsigned bi=0;bi<scene_->mMeshes[mi]->mNumBones;++bi){aiBone* b=scene_->mMeshes[mi]->mBones[bi];if(!boneIds_.count(b->mName.C_Str())){unsigned id=static_cast<unsigned>(boneIds_.size());if(id>=128){std::cerr<<"Model exceeds 128-bone skin limit: "<<path<<'\n';continue;}boneIds_[b->mName.C_Str()]=id;offsets_.push_back(b->mOffsetMatrix);}}
    fallbackTexture_=loadTexture(fallbackTexture);if(!fallbackTexture_){const unsigned char white[]={255,255,255,255};glGenTextures(1,&fallbackTexture_);glBindTexture(GL_TEXTURE_2D,fallbackTexture_);glTexImage2D(GL_TEXTURE_2D,0,GL_RGBA8,1,1,0,GL_RGBA,GL_UNSIGNED_BYTE,white);glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_MIN_FILTER,GL_LINEAR);glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_MAG_FILTER,GL_LINEAR);}
    for(unsigned mi=0;mi<scene_->mNumMeshes;++mi){aiMesh* src=scene_->mMeshes[mi];std::vector<Vertex> vertices(src->mNumVertices);std::vector<unsigned> indices;indices.reserve(src->mNumFaces*3);
        for(unsigned i=0;i<src->mNumVertices;++i){auto& v=vertices[i];v.p={src->mVertices[i].x,src->mVertices[i].y,src->mVertices[i].z};v.n=src->HasNormals()?glm::vec3(src->mNormals[i].x,src->mNormals[i].y,src->mNormals[i].z):glm::vec3(0,1,0);v.uv=src->HasTextureCoords(0)?glm::vec2(src->mTextureCoords[0][i].x,src->mTextureCoords[0][i].y):glm::vec2(0);v.color=glm::vec3(1);}
        for(unsigned bi=0;bi<src->mNumBones;++bi){aiBone* b=src->mBones[bi];auto found=boneIds_.find(b->mName.C_Str());if(found==boneIds_.end()||found->second>=128)continue;for(unsigned wi=0;wi<b->mNumWeights;++wi){auto& v=vertices[b->mWeights[wi].mVertexId];float w=b->mWeights[wi].mWeight;for(int slot=0;slot<4;++slot)if(v.weights[slot]==0.f){v.boneIds[slot]=static_cast<int>(found->second);v.weights[slot]=w;break;}}}
        for(auto& v:vertices){float total=v.weights.x+v.weights.y+v.weights.z+v.weights.w;if(total>0)v.weights/=total;}
        for(unsigned f=0;f<src->mNumFaces;++f)for(unsigned j=0;j<src->mFaces[f].mNumIndices;++j)indices.push_back(src->mFaces[f].mIndices[j]);
        Mesh m;m.indices=static_cast<GLsizei>(indices.size());if(src->mMaterialIndex<scene_->mNumMaterials){aiMaterial* mat=scene_->mMaterials[src->mMaterialIndex];aiString materialName;mat->Get(AI_MATKEY_NAME,materialName);m.materialName=materialName.C_Str();aiColor3D c(1.f,1.f,1.f);if(mat->Get(AI_MATKEY_BASE_COLOR,c)!=AI_SUCCESS)mat->Get(AI_MATKEY_COLOR_DIFFUSE,c);m.color={c.r,c.g,c.b};aiString texPath;if(mat->GetTexture(aiTextureType_BASE_COLOR,0,&texPath)!=AI_SUCCESS)mat->GetTexture(aiTextureType_DIFFUSE,0,&texPath);if(texPath.length){std::string name=texPath.C_Str();if(name.size()&&name[0]=='*'){unsigned ti=static_cast<unsigned>(std::stoi(name.substr(1)));if(ti<scene_->mNumTextures){const aiTexture* t=scene_->mTextures[ti];if(t->mHeight==0){int w,h,n;auto* data=stbi_load_from_memory(reinterpret_cast<const unsigned char*>(t->pcData),static_cast<int>(t->mWidth),&w,&h,&n,4);if(data){glGenTextures(1,&m.texture);glBindTexture(GL_TEXTURE_2D,m.texture);glTexImage2D(GL_TEXTURE_2D,0,GL_SRGB8_ALPHA8,w,h,0,GL_RGBA,GL_UNSIGNED_BYTE,data);glGenerateMipmap(GL_TEXTURE_2D);glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_MIN_FILTER,GL_LINEAR_MIPMAP_LINEAR);glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_MAG_FILTER,GL_LINEAR);stbi_image_free(data);}}}}else m.texture=loadTexture((std::filesystem::path(directory_)/name).string());}}
        // A caller-supplied albedo is the material for assets with no embedded diffuse map; avoid multiplying it by exporter placeholder gray.
        if(fallbackTexture_&&!m.texture)m.color=glm::vec3(1.f);
        glGenVertexArrays(1,&m.vao);glGenBuffers(1,&m.vbo);glGenBuffers(1,&m.ebo);glBindVertexArray(m.vao);glBindBuffer(GL_ARRAY_BUFFER,m.vbo);glBufferData(GL_ARRAY_BUFFER,vertices.size()*sizeof(Vertex),vertices.data(),GL_STATIC_DRAW);glBindBuffer(GL_ELEMENT_ARRAY_BUFFER,m.ebo);glBufferData(GL_ELEMENT_ARRAY_BUFFER,indices.size()*sizeof(unsigned),indices.data(),GL_STATIC_DRAW);
        glVertexAttribPointer(0,3,GL_FLOAT,GL_FALSE,sizeof(Vertex),(void*)offsetof(Vertex,p));glEnableVertexAttribArray(0);glVertexAttribPointer(1,3,GL_FLOAT,GL_FALSE,sizeof(Vertex),(void*)offsetof(Vertex,color));glEnableVertexAttribArray(1);glVertexAttribPointer(2,3,GL_FLOAT,GL_FALSE,sizeof(Vertex),(void*)offsetof(Vertex,n));glEnableVertexAttribArray(2);glVertexAttribPointer(3,2,GL_FLOAT,GL_FALSE,sizeof(Vertex),(void*)offsetof(Vertex,uv));glEnableVertexAttribArray(3);glVertexAttribIPointer(4,4,GL_INT,sizeof(Vertex),(void*)offsetof(Vertex,boneIds));glEnableVertexAttribArray(4);glVertexAttribPointer(5,4,GL_FLOAT,GL_FALSE,sizeof(Vertex),(void*)offsetof(Vertex,weights));glEnableVertexAttribArray(5);meshes_.push_back(m);
    }
    return !meshes_.empty();
}
void Model::visitNode(aiNode* node,const aiMatrix4x4& parent,const std::unordered_map<std::string,const aiNodeAnim*>& channels,const aiAnimation* anim,double t,bool proceduralZombie,bool hitReaction,std::vector<glm::mat4>& out){
    aiMatrix4x4 local=node->mTransformation;auto it=channels.find(node->mName.C_Str());if(it!=channels.end()&&anim){const aiNodeAnim* ch=it->second;double ticks=t*(anim->mTicksPerSecond>0?anim->mTicksPerSecond:25.0);auto vecAt=[&](const aiVectorKey* keys,unsigned n,aiVector3D fallback){if(!n)return fallback;if(n==1||ticks<=keys[0].mTime)return keys[0].mValue;if(ticks>=keys[n-1].mTime)return keys[n-1].mValue;unsigned i=0;while(i+1<n&&ticks>=keys[i+1].mTime)++i;double span=keys[i+1].mTime-keys[i].mTime;float a=span>0?float((ticks-keys[i].mTime)/span):0.f;return keys[i].mValue+(keys[i+1].mValue-keys[i].mValue)*a;};auto quatAt=[&](const aiQuatKey* keys,unsigned n,aiQuaternion fallback){if(!n)return fallback;if(n==1||ticks<=keys[0].mTime)return keys[0].mValue;if(ticks>=keys[n-1].mTime)return keys[n-1].mValue;unsigned i=0;while(i+1<n&&ticks>=keys[i+1].mTime)++i;double span=keys[i+1].mTime-keys[i].mTime;float a=span>0?float((ticks-keys[i].mTime)/span):0.f;aiQuaternion q;aiQuaternion::Interpolate(q,keys[i].mValue,keys[i+1].mValue,a);q.Normalize();return q;};aiVector3D scale,pos;aiQuaternion rot;local.Decompose(scale,rot,pos);scale=vecAt(ch->mScalingKeys,ch->mNumScalingKeys,scale);pos=vecAt(ch->mPositionKeys,ch->mNumPositionKeys,pos);rot=quatAt(ch->mRotationKeys,ch->mNumRotationKeys,rot);local=aiMatrix4x4(scale,rot,pos);}
    if(proceduralZombie){std::string name=node->mName.C_Str();bool left=name.find("L_")!=std::string::npos;float phase=float(t)*6.f+(left?0.f:3.14159f),swing=std::sin(phase);aiVector3D sc,pos;aiQuaternion rot;local.Decompose(sc,rot,pos);float angle=0.f;if(name.find("Thigh")!=std::string::npos||name.find("UpperLeg")!=std::string::npos)angle=swing*.34f;if(name.find("Calf")!=std::string::npos||name.find("LowerLeg")!=std::string::npos)angle=std::max(0.f,-swing)*.52f;if(name.find("Upperarm")!=std::string::npos||name.find("UpperArm")!=std::string::npos)angle=-swing*.22f-.18f;if(name.find("Forearm")!=std::string::npos)angle=.24f+std::max(0.f,swing)*.34f;if(name.find("Spine")!=std::string::npos)angle=std::sin(float(t)*3.f)*.04f+(hitReaction?.24f:0.f);if(name.find("Head")!=std::string::npos&&hitReaction)angle=-.18f;rot=rot*aiQuaternion(aiVector3D(1,0,0),angle);if(name.find("Upperarm")!=std::string::npos||name.find("UpperArm")!=std::string::npos){float side=name.find("L_")!=std::string::npos?1.f:-1.f;rot=rot*aiQuaternion(aiVector3D(0,0,1),side*.72f);}local=aiMatrix4x4(sc,rot,pos);}
    aiMatrix4x4 global=parent*local;auto b=boneIds_.find(node->mName.C_Str());if(b!=boneIds_.end()&&b->second<out.size())out[b->second]=globalInverse_*toGlm(global)*toGlm(offsets_[b->second]);for(unsigned i=0;i<node->mNumChildren;++i)visitNode(node->mChildren[i],global,channels,anim,t,proceduralZombie,hitReaction,out);
}
void Model::draw(GLuint shader,const glm::mat4& transform,const std::string& clip,float seconds,const glm::vec3& tint){if(!valid())return;bool proceduralZombie=(clip=="ProceduralZombie"||clip=="ZombieHit"||clip=="ZombieProc");bool hitReaction=clip=="ZombieHit";const aiAnimation* anim=nullptr;if(!clip.empty()&&!proceduralZombie)for(unsigned i=0;i<scene_->mNumAnimations&&!anim;++i)if(std::string(scene_->mAnimations[i]->mName.C_Str()).find(clip)!=std::string::npos)anim=scene_->mAnimations[i];std::unordered_map<std::string,const aiNodeAnim*> channels;if(anim){for(unsigned i=0;i<anim->mNumChannels;++i)channels[anim->mChannels[i]->mNodeName.C_Str()]=anim->mChannels[i];double d=anim->mDuration/(anim->mTicksPerSecond>0?anim->mTicksPerSecond:25.0);if(d>0)seconds=std::fmod(std::max(0.f,seconds),d);}glUseProgram(shader);if(cachedShader_!=shader){cachedShader_=shader;modelUniform_=glGetUniformLocation(shader,"model");bonesUniform_=glGetUniformLocation(shader,"bones[0]");skinnedUniform_=glGetUniformLocation(shader,"skinned");useTextureUniform_=glGetUniformLocation(shader,"useTexture");baseColorUniform_=glGetUniformLocation(shader,"baseColor");albedoUniform_=glGetUniformLocation(shader,"albedo");zombiePoseUniform_=glGetUniformLocation(shader,"zombiePose");zombiePhaseUniform_=glGetUniformLocation(shader,"zombiePhase");}glUniformMatrix4fv(modelUniform_,1,GL_FALSE,glm::value_ptr(transform));bool bindPoseOnly=proceduralZombie||clip=="BindPose";bool skinned=!boneIds_.empty()&&!bindPoseOnly;glUniform1i(zombiePoseUniform_,clip=="ZombieProc"?1:0);glUniform1f(zombiePhaseUniform_,seconds);if(skinned){std::vector<glm::mat4> bones(128,glm::mat4(1));aiMatrix4x4 identity;visitNode(scene_->mRootNode,identity,channels,anim,seconds,proceduralZombie,hitReaction,bones);glUniformMatrix4fv(bonesUniform_,128,GL_FALSE,glm::value_ptr(bones[0]));}glUniform1i(skinnedUniform_,skinned?1:0);for(const auto& m:meshes_){glm::vec3 color=m.color*tint;if(m.materialName.find("leaf")!=std::string::npos||m.materialName.find("Leaf")!=std::string::npos||m.materialName.find("grass")!=std::string::npos)color*=glm::vec3(.72f,1.10f,.58f);else if(m.materialName.find("wood")!=std::string::npos||m.materialName.find("Wood")!=std::string::npos||m.materialName.find("bark")!=std::string::npos)color*=glm::vec3(1.10f,.72f,.46f);glUniform3fv(baseColorUniform_,1,glm::value_ptr(color));GLuint texture=m.texture?m.texture:fallbackTexture_;glUniform1i(useTextureUniform_,texture?1:0);glActiveTexture(GL_TEXTURE0);glBindTexture(GL_TEXTURE_2D,texture);glUniform1i(albedoUniform_,0);glBindVertexArray(m.vao);glDrawElements(GL_TRIANGLES,m.indices,GL_UNSIGNED_INT,0);}glUniform1i(useTextureUniform_,0);glUniform1i(skinnedUniform_,0);glUniform1i(zombiePoseUniform_,0);}
